#!/usr/bin/env python3
"""Build data/tickets.jsonl: synthetic support tickets, generated by one model, labelled blind by two others.

1. GENERATE  GEN_MODEL (used: baidu/ernie-5.5-flash-preview:free) writes 10 batches x 25 tickets for "Lumen",
             a made-up B2B analytics SaaS. Each batch has a fixed quota (5 per department, an urgency mix,
             6-7 deliberately borderline tickets) and a different writing persona, so the set is varied and
             balanced by construction. The generator also records the label it intended.
2. LABEL     two other models label every ticket WITHOUT seeing the intended label (LABEL_MODELS, used:
             particle-ai/particle-1:free and openai/gpt-6-luna), 25 tickets per call, the same label
             descriptions every method in the workshop sees (common.py).
3. RESOLVE   gold = majority of (generator intent, labeller 1, labeller 2). If the two blind labellers
             disagree on the department, the ticket is marked ambiguous=true.
4. SPLIT     100 train (only the classic classifier learns from them) / 150 test (every method is scored here).

Every raw model output is cached in data/raw/, so a re-run only calls what is missing.
Run:  GEN_MODEL=... LABEL_MODELS=a,b python data/make_dataset.py   (the committed run cost $0.006)
See data/DATASET.md for the numbers and the caveats.
"""
import json, random, sys, pathlib, time
from concurrent.futures import ThreadPoolExecutor
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parents[1]))
from common import DEPARTMENTS, URGENCY
import llm

HERE = pathlib.Path(__file__).parent

import os
GENERATOR = os.environ.get("GEN_MODEL", "nvidia/nemotron-3-ultra-550b-a55b:free")
LABELLERS = os.environ.get("LABEL_MODELS", "google/gemma-4-31b-it:free,openai/gpt-6-luna").split(",")
RAW = HERE / "raw"
PERSONAS = [
    "a terse IT admin at a mid-size retailer, short sentences, no greetings",
    "an upset small-business owner, emotional, some caps, mentions their own customers",
    "a non-native English speaker, small grammar mistakes, polite",
    "a backend developer, precise, pastes error codes, endpoint names and timestamps",
    "a finance/procurement person at an enterprise, formal, references PO numbers and contracts",
    "someone typing on a phone: lowercase, typos, no punctuation, very short",
    "a marketing analyst who uses dashboards daily, friendly, a bit chatty, mixes two topics",
    "a new trial user who is confused by the product and the terminology",
    "an agency managing several client workspaces, mentions client names and seats",
    "a security-conscious CTO, mentions SSO, audit, compliance, deadlines",
]
PRODUCT = ("Lumen: a B2B analytics SaaS. Web app with dashboards and scheduled reports, a REST API and webhooks, "
           "connectors (Salesforce, Shopify, Postgres, BigQuery), a mobile app, per-seat plans "
           "(Starter, Team, Enterprise), annual or monthly billing, SSO/2FA, workspaces with owners and roles.")
GEN_SCHEMA = {"type": "object", "additionalProperties": False, "required": ["tickets"], "properties": {"tickets": {
    "type": "array", "items": {"type": "object", "additionalProperties": False,
        "required": ["text", "department", "urgency", "borderline", "also_plausible"],
        "properties": {"text": {"type": "string"}, "department": {"type": "string", "enum": list(DEPARTMENTS)},
                       "urgency": {"type": "string", "enum": list(URGENCY)}, "borderline": {"type": "boolean"},
                       "also_plausible": {"type": "string", "enum": list(DEPARTMENTS) + ["none"]}}}}}}
LAB_SCHEMA = {"type": "object", "additionalProperties": False, "required": ["labels"], "properties": {"labels": {
    "type": "array", "items": {"type": "object", "additionalProperties": False,
        "required": ["id", "department", "urgency"],
        "properties": {"id": {"type": "integer"}, "department": {"type": "string", "enum": list(DEPARTMENTS)},
                       "urgency": {"type": "string", "enum": list(URGENCY)}}}}}}


def described(d):
    return "\n".join(f"- {k}: {v}" for k, v in d.items())


def generate(batch):
    rnd = random.Random(batch)
    urg = ["low"] * 10 + ["medium"] * 9 + ["high"] * 6
    rnd.shuffle(urg)
    plan = [f"{i+1}. department={d}, urgency={urg[i]}" + (", BORDERLINE (could reasonably be read as another department)" if i % 4 == 1 else "")
            for i, d in enumerate([d for d in DEPARTMENTS for _ in range(5)])]
    prompt = f"""You write realistic customer support tickets for a dataset.
Product: {PRODUCT}

Departments:
{described(DEPARTMENTS)}
Urgency:
{described(URGENCY)}

Write exactly 25 tickets, one per line of this plan, in this order:
{chr(10).join(plan)}

Voice for this whole batch: {PERSONAS[batch]}.
Rules: 1-5 sentences each, varied length and openings; concrete details (numbers, features, names of made-up
companies/people); never mention the department name or the word urgency; no two tickets about the same thing.
BORDERLINE tickets must genuinely mix two departments (e.g. a failed payment that is really a bug, a seat question
that is really an upgrade purchase); still pick the department a careful support lead would choose, and put the
other one in also_plausible. For non-borderline tickets set borderline=false and also_plausible="none"."""
    cache = RAW / f"gen_{batch}.json"
    if cache.exists():
        return json.load(open(cache))
    prompt += '\n\nReturn JSON only: {"tickets": [{"text", "department", "urgency", "borderline", "also_plausible"}, ...]}'
    for attempt in range(3):
        try:
            r = llm.chat(GENERATOR, [{"role": "user", "content": prompt}], max_tokens=16000, temperature=1.0,
                         schema=GEN_SCHEMA, reasoning="low")
            rows = llm.parse_json(r["text"])["tickets"]
            if len(rows) == 25:
                break
        except (ValueError, KeyError, RuntimeError) as e:
            print("generate retry", batch, str(e)[:200], flush=True)
            rows = []
            time.sleep(20)
    print("generated batch", batch, len(rows), round(r["ms"] / 1000), "s", flush=True)
    out = [rows, {k: v for k, v in r.items() if k not in ("text", "logprobs")}]
    json.dump(out, open(cache, "w"), ensure_ascii=False)
    return out


def label(model, rows):
    items = "\n".join(json.dumps({"id": r["id"], "text": r["text"]}, ensure_ascii=False) for r in rows)
    prompt = f"""Label each support ticket of a B2B analytics SaaS with the department that should own it and its urgency.
Departments:
{described(DEPARTMENTS)}
Urgency:
{described(URGENCY)}

Tickets (JSON lines):
{items}

Return a label for every id."""
    cache = RAW / f"label_{model.replace('/', '_').replace(':', '_')}_{rows[0]['id']}.json"
    if cache.exists():
        return json.load(open(cache))
    prompt += '\nReturn JSON only: {"labels": [{"id", "department", "urgency"}, ...]}'
    for attempt in range(3):
        try:
            r = llm.chat(model, [{"role": "user", "content": prompt}], max_tokens=4000, temperature=0.0,
                         schema=LAB_SCHEMA, reasoning=None if ":free" in model else "minimal")
            labs = {l["id"]: l for l in llm.parse_json(r["text"])["labels"]}
            if len(labs) >= len(rows):
                break
        except (ValueError, KeyError, RuntimeError) as e:
            print("label retry", model, e)
    out = [{str(k): v for k, v in labs.items()}, {k: v for k, v in r.items() if k not in ("text", "logprobs")}]
    json.dump(out, open(cache, "w"))
    return out


def main():
    RAW.mkdir(exist_ok=True)
    log = {"generator": GENERATOR, "labellers": LABELLERS, "started": time.strftime("%Y-%m-%dT%H:%M:%S%z"), "calls": []}
    with ThreadPoolExecutor(int(os.environ.get("GEN_WORKERS", "2"))) as ex:
        batches = list(ex.map(generate, range(len(PERSONAS))))
    rows = []
    for b, (ts, r) in enumerate(batches):
        log["calls"].append({"step": "generate", "batch": b, "model": r["model"], "in_tok": r["in_tok"], "out_tok": r["out_tok"], "cost": r["cost"], "ms": round(r["ms"])})
        for t in ts:
            rows.append({"text": t["text"].strip(), "intent_department": t["department"], "intent_urgency": t["urgency"],
                         "borderline": t["borderline"], "also_plausible": t["also_plausible"], "persona": b})
    random.Random(42).shuffle(rows)
    for i, r in enumerate(rows):
        r["id"] = i
    chunks = [rows[i:i + 25] for i in range(0, len(rows), 25)]
    for m in LABELLERS:
        with ThreadPoolExecutor(5) as ex:
            outs = list(ex.map(lambda c: label(m, c), chunks))
        for c, (labs, r) in zip(chunks, outs):
            log["calls"].append({"step": "label", "model": r["model"], "in_tok": r["in_tok"], "out_tok": r["out_tok"], "cost": r["cost"], "ms": round(r["ms"])})
            for t in c:
                l = labs.get(str(t["id"]), {})
                t.setdefault("labels", {})[m] = {"department": l.get("department"), "urgency": l.get("urgency")}
    out = []
    for i, r in enumerate(rows):
        l1, l2 = (r["labels"][m] for m in LABELLERS)
        def maj(key, intent):
            votes = [intent, l1[key], l2[key]]
            best = max(set(votes), key=votes.count)
            return best if votes.count(best) >= 2 else intent
        out.append({"id": r["id"], "split": "train" if i < 100 else "test", "text": r["text"],
                    "department": maj("department", r["intent_department"]), "urgency": maj("urgency", r["intent_urgency"]),
                    "ambiguous": l1["department"] != l2["department"],
                    "generator_borderline": r["borderline"], "also_plausible": r["also_plausible"],
                    "intent": {"department": r["intent_department"], "urgency": r["intent_urgency"]},
                    "labels": r["labels"], "persona": r["persona"]})
    with open(HERE / "tickets.jsonl", "w") as f:
        for r in out:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    agree = lambda a, b: sum(a(r) == b(r) for r in out) / len(out)
    log["stats"] = {
        "n": len(out), "train": 100, "test": len(out) - 100,
        "ambiguous": sum(r["ambiguous"] for r in out),
        "dept_agree_labellers": agree(lambda r: r["labels"][LABELLERS[0]]["department"], lambda r: r["labels"][LABELLERS[1]]["department"]),
        "dept_agree_intent_vs_gold": agree(lambda r: r["intent"]["department"], lambda r: r["department"]),
        "urgency_agree_labellers": agree(lambda r: r["labels"][LABELLERS[0]]["urgency"], lambda r: r["labels"][LABELLERS[1]]["urgency"]),
        "total_cost_usd": round(sum(c["cost"] for c in log["calls"]), 4)}
    json.dump(log, open(HERE / "generation_log.json", "w"), indent=1)
    print(json.dumps(log["stats"], indent=1))


if __name__ == "__main__":
    main()
